// The equivalence test of xr.request, airframe.apply and the repository methods apply calls (A-9 S5c): testdata/airframe.json is
// generated by driving the Python code (tools/gen_gateway_airframe.py: gateway.hangar_handlers over github_pr.GitHubPRs, the
// planner and glidepath-api) over canned upstream answers, and every case here serves the same answers and requires the same
// result, refusal or error text and the exact requests, in order. A case with "go" is a place Go deliberately differs, and "why"
// says why; its "requests" are Go's exact list. File contents in a pull request's tree are compared as the YAML they hold (Go keeps
// an agent's keys in sorted order and Python in the order they were sent, and the two emitters quote differently).

// airframeFixture is the registry the fixture uses.
var airframeFixtureRegistry = airframe.Registry{DevCluster: "dev-cluster", UpperClusters: []string{"up-cluster"}, TenantsRepo: "gitops-tenants", Owner: "o"}

func airframeDefinition(reg *tools.Registry) (*definitions.Definition, []string) {
	d := &definitions.Definition{Name: "fixture-agent", Kind: "task", ReposAllow: []string{"o/*"}, DenyPaths: reg.BaselineDenyPaths,
		RawProfile: []byte(`{"glidepath":{"apps":["*"]},"airframe":{"apps":["*"],"proposeFlight":true}}`)}
	return d, reg.Names()
}

func newAirframeEnv(t *testing.T, tok map[string]string, c *writesCase) *env {
	t.Helper()
	w := newWorld(t, c.Routes, c.Default)
	dir := t.TempDir()
	write := func(name, v string) string {
		p := filepath.Join(dir, name)
		if err := os.WriteFile(p, []byte(v+"\n"), 0o600); err != nil {
			t.Fatal(err)
		}
		return p
	}
	reg := tools.Default()
	def, names := airframeDefinition(reg)
	cfg := HangarConfig{Definition: func(string) *definitions.Definition { return def }, Tools: reg,
		Airframe: &AirframeConfig{Enabled: true, XRRequests: true, Registry: airframeFixtureRegistry}}
	e := &env{w: w, sess: fixtureSession(c.Session, names)}
	gp, err := NewGlidepath(w.srv.URL+"/gp", write("gp", tok["glidepath"]), false, 5*time.Second, true)
	if err != nil {
		t.Fatal(err)
	}
	asClient(w, gp.hc)
	asClient(w, gp.streamHC)
	gp.retry.retries = 0
	cfg.Glidepath, e.gp = gp, gp
	g, err := NewGitHub(GitHubOptions{API: w.srv.URL, BrokerURL: w.srv.URL + "/b", TokenFile: write("agent", tok["agent"]), Owners: []string{"o"},
		TenantsRepo: "o/gitops-tenants", AllowHTTP: true, AllowHTTPAPI: true, Timeout: 5 * time.Second})
	if err != nil {
		t.Fatal(err)
	}
	asClient(w, g.apiHC)
	asClient(w, g.brokerHC)
	g.retry.retries = 0
	cfg.GitHub, e.git = g, g
	e.h = hangarHandlers(cfg)
	return e
}

// treeYAML replaces each file of a tree request by the YAML it holds, so two emitters that spell the same document differently
// compare equal; a file that is not YAML (a cicd.yaml text from glidepath-api) is compared as it is.
func treeYAML(t *testing.T, reqs any) any {
	t.Helper()
	l, ok := reqs.([]any)
	if !ok {
		return reqs
	}
	for _, r := range l {
		m, ok := r.(map[string]any)
		if !ok || m["method"] != "POST" || !strings.HasSuffix(m["target"].(string), "/git/trees") {
			continue
		}
		body, _ := m["body"].(map[string]any)
		for _, e := range anyList(body["tree"]) {
			ent, ok := e.(map[string]any)
			if !ok {
				continue
			}
			var v any
			if s, isStr := ent["content"].(string); isStr && yaml.Unmarshal([]byte(s), &v) == nil {
				ent["content"] = map[string]any{"$yaml": normalize(t, v)}
			}
		}
	}
	return reqs
}

func runAirframeDirect(ctx context.Context, e *env, method string, a map[string]any) (any, error) {
	repo, _ := a["repo"].(string)
	tenants, _ := a["tenants"].(bool)
	switch method {
	case "pr_paths":
		n, _ := a["number"].(int64)
		if jn, ok := a["number"].(interface{ Int64() (int64, error) }); ok {
			n, _ = jn.Int64()
		}
		return e.git.PRPaths(ctx, repo, n, tenants)
	case "repo_ready":
		return e.git.RepoReady(ctx, repo, tenants)
	case "onboarding_prs":
		return e.git.OnboardingPRs(ctx, repo, tenants)
	case "read_file":
		return e.git.ReadFileIn(ctx, repo, str(a, "path"), tenants)
	case "find_pr":
		m, err := e.git.FindPRIn(ctx, repo, str(a, "branch"), tenants, map[string]string{"agent": "fixture-agent", "task": "t-abc123", "session": "s-1", "run": "r-1"})
		if m == nil && err == nil {
			return nil, nil
		}
		return m, err
	}
	return nil, errors.New("no such method " + method)
}

func TestAirframeToolsEqualPython(t *testing.T) {
	var f writesFile
	loadJSON(t, "airframe.json", &f)
	if len(f.Cases) < 70 {
		t.Fatalf("only %d cases: the fixture is not the one the generator writes", len(f.Cases))
	}
	n := map[string]int{}
	for _, c := range f.Cases {
		n[c.Tool]++
		switch {
		case c.Go != nil:
			n["differs"]++
		case c.Denied != nil:
			n["denied"]++
		case c.Error != nil:
			n["error"]++
		default:
			n["result"]++
		}
		t.Run(c.Name, func(t *testing.T) {
			e := newAirframeEnv(t, f.Tokens, &c)
			args := expand(c.Args).(map[string]any) // what Go is given (Python may have been given a part written out: py_args)
			var got any
			var err error
			ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
			defer cancel()
			if strings.HasPrefix(c.Tool, "direct:") {
				got, err = runAirframeDirect(ctx, e, strings.TrimPrefix(c.Tool, "direct:"), args)
			} else {
				h := e.h[c.Tool]
				if h == nil {
					t.Fatalf("no handler for %s", c.Tool)
				}
				got, err = h(ctx, e.sess, args)
			}
			wantReqs, wantResult, wantDenied, wantErr := c.Requests, c.Result, c.Denied, c.Error
			if c.GoRequests != nil {
				wantReqs = c.GoRequests
			}
			if c.Go != nil {
				if c.Why == "" {
					t.Fatal("a case Go answers differently says why")
				}
				wantResult, wantDenied, wantErr = c.Go.Result, c.Go.Denied, c.Go.Error
				if c.Go.Requests != nil {
					wantReqs = *c.Go.Requests
				}
			}
			gotReqs := e.requests()
			if len(wantReqs) == 0 {
				wantReqs = nil
			}
			if len(gotReqs) == 0 {
				gotReqs = nil
			}
			wantN, gotN := treeYAML(t, normalize(t, expand(normalize(t, wantReqs)))), treeYAML(t, normalize(t, gotReqs))
			if !reflect.DeepEqual(wantN, gotN) {
				t.Fatalf("requests (the call answered %s / %v)\n want %s\n  got %s", short(got), err, short(wantN), short(gotN))
			}
			switch {
			case wantDenied != nil:
				var den *core.Denied
				if !errors.As(err, &den) {
					t.Fatalf("want a refusal %+v, got %v / %v", wantDenied, short(got), err)
				}
				if any(den.Rule) != wantDenied.Rule || any(den.Message) != wantDenied.Message || any(den.Hint) != wantDenied.Hint {
					t.Fatalf("refusal\n want %+v\n  got %+v", wantDenied, den)
				}
			case wantErr != nil:
				if err == nil {
					t.Fatalf("want error %+v, got %v", wantErr, short(got))
				}
				if r := dispatch.ErrorResult(err); r != wantErr.OutcomeResult {
					t.Fatalf("outcome result:\n want %q\n  got %q", wantErr.OutcomeResult, r)
				}
				if m := dispatch.BackendError(err); m != wantErr.AgentError {
					t.Fatalf("agent error:\n want %q\n  got %q", wantErr.AgentError, m)
				}
			default:
				if err != nil {
					t.Fatalf("want a result, got %v", err)
				}
				want := scrubAt(normalize(t, expand(wantResult)))
				have := scrubAt(normalize(t, got))
				if !reflect.DeepEqual(want, have) {
					t.Fatalf("result\n want %s\n  got %s", short(want), short(have))
				}
				if spec, ok := tools.Default().Get(c.Tool); ok {
					// the receipt the outcome carries is Python's for the same result (with Go's branch name)
					wantEffect, gotEffect := dropEmpty(normalize(t, c.Effect)), dropEmpty(normalize(t, dispatch.Effect(spec, args, got)))
					if c.Go != nil {
						wantEffect = dropEmpty(normalize(t, c.Go.Effect))
					}
					if !reflect.DeepEqual(wantEffect, gotEffect) {
						t.Fatalf("effect\n want %s\n  got %s", short(wantEffect), short(gotEffect))
					}
				}
			}
		})
	}
	if n["xr.request"] < 35 || n["airframe.apply"] < 15 || n["differs"] < 30 || n["denied"] < 10 || n["result"] < 10 {
		t.Fatalf("the fixture's cases: %v", n)
	}
}
